    saveRecoveryNote: "ເກັບລະຫັດນີ້ເປັນສ່ວນຕົວ. ໃຜທີ່ມີມັນ ແລະ ບັນຊີໂຮງຮຽນຂອງເຈົ້າສາມາດກູ້ຄືນກະແຈສົນທະນາຂອງເຈົ້າໄດ້. ມັນຈະບໍ່ສະແດງອີກຫຼັງຈາກເຈົ້າຢືນຢັນວ່າບັນທຶກແລ້ວ.",
