// All languages the UI can be shown in: [code, native name]. Each code is a key of STRINGS.
export const LANGUAGES = [
  ['en', 'English'],
  ['ja', '日本語'],
  ['my', 'မြန်မာ'],
  ['vi', 'Tiếng Việt'],
  ['th', 'ไทย'],
  ['id', 'Bahasa Indonesia'],
  ['tl', 'Filipino'],
  ['km', 'ខ្មែរ'],
  ['lo', 'ລາວ'],
  ['zh-CN', '简体中文'],
  ['zh-TW', '繁體中文'],
  ['ko', '한국어'],
  ['mn', 'Монгол'],
  ['ne', 'नेपाली'],
  ['hi', 'हिन्दी'],
  ['bn', 'বাংলা'],
  ['si', 'සිංහල'],
  ['ur', 'اردو'],
  ['es', 'Español'],
  ['pt', 'Português'],
  ['fr', 'Français'],
  ['ru', 'Русский'],
  ['ar', 'العربية'],
];

const LANG_CODES = new Set(LANGUAGES.map(([code]) => code));

// BCP-47 locale used to format dates and times for each UI language.
export const LOCALES = {
  en: 'en-US', ja: 'ja-JP', my: 'my-MM', vi: 'vi-VN', th: 'th-TH', id: 'id-ID',
  tl: 'fil-PH', km: 'km-KH', lo: 'lo-LA', 'zh-CN': 'zh-CN', 'zh-TW': 'zh-TW',
  ko: 'ko-KR', mn: 'mn-MN', ne: 'ne-NP', hi: 'hi-IN', bn: 'bn-BD', si: 'si-LK',
  ur: 'ur-PK', es: 'es-ES', pt: 'pt-BR', fr: 'fr-FR', ru: 'ru-RU', ar: 'ar',
};

export function localeFor(lang) {
  return LOCALES[lang] ?? 'en-US';
}

const STORAGE_KEY = 'campconnect_lang';

export function translate(lang, key, vars) {
  const text = STRINGS[lang]?.[key] ?? STRINGS.en[key] ?? key;
  return vars ? text.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? '') : text;
}

// Map a browser language tag (e.g. "pt-BR", "zh-Hant-TW") to one of our codes, if we have it.
function langFromBrowser(tag) {
  if (!tag) return null;
  const lower = tag.toLowerCase();
  if (lower.startsWith('zh')) {
    return (lower.includes('tw') || lower.includes('hk') || lower.includes('mo') || lower.includes('hant')) ? 'zh-TW' : 'zh-CN';
  }
  const prefix = lower.split('-')[0];
  if (prefix === 'fil') return 'tl';
  if (prefix === 'in') return 'id'; // legacy tag for Indonesian
  return LANG_CODES.has(prefix) ? prefix : null;
}

// A saved choice wins; otherwise follow the browser's language.
export function initialLang() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (LANG_CODES.has(saved)) return saved;
  } catch { /* storage unavailable */ }
  return langFromBrowser(navigator.language) ?? 'en';
}

export function saveLang(lang) {
  try { localStorage.setItem(STORAGE_KEY, lang); } catch { /* storage unavailable */ }
}
